draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
var m1 = p.m1, m2 = p.m2, F = p.force;
var a = F / (m1 + m2);
var Cf = m2 * a;

var arrow = function (x, y, dx, dy, label, lx, ly) {
  var ex = x + dx, ey = y + dy;
  ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(ex, ey); ctx.stroke();
  var len = Math.sqrt(dx * dx + dy * dy);
  if (len > 1) {
    var hx = dx / len, hy = dy / len;
    ctx.beginPath();
    ctx.moveTo(ex, ey);
    ctx.lineTo(ex - 7 * hx + 4 * hy, ey - 7 * hy - 4 * hx);
    ctx.lineTo(ex - 7 * hx - 4 * hy, ey - 7 * hy + 4 * hx);
    ctx.closePath(); ctx.fill();
  }
  ctx.fillStyle = C.ink;
  ctx.fillText(label, ex + lx, ey + ly);
};

// ---- top: the real picture ----
var fy = H * 0.36;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(W * 0.08, fy); ctx.lineTo(W * 0.92, fy); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("the real picture", W * 0.08, H * 0.09);

var h1 = 26 + m1 * 4, h2 = 26 + m2 * 4;
var w1 = 44, w2 = 44;
var bx = W * 0.36;
ctx.fillStyle = C.paper; ctx.strokeStyle = C.ink;
ctx.fillRect(bx, fy - h1, w1, h1); ctx.strokeRect(bx, fy - h1, w1, h1);
ctx.fillRect(bx + w1, fy - h2, w2, h2); ctx.strokeRect(bx + w1, fy - h2, w2, h2);
ctx.fillStyle = C.ink;
ctx.fillText("m1", bx + 14, fy - h1 / 2 + 4);
ctx.fillText("m2", bx + w1 + 14, fy - h2 / 2 + 4);
arrow(bx - 48, fy - h1 / 2, 44, 0, "F", -46, -8);

// ---- bottom: one diagram per object ----
ctx.fillStyle = C.ink;
ctx.fillText("one free body diagram per object", W * 0.08, H * 0.56);
var by = H * 0.79;
var c1 = W * 0.28, c2 = W * 0.68;
ctx.setLineDash([4, 4]);
ctx.strokeStyle = C.rule;
ctx.strokeRect(c1 - 22, by - 20, 44, 40);
ctx.strokeRect(c2 - 22, by - 20, 44, 40);
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("m1", c1 - 8, by + 4);
ctx.fillText("m2", c2 - 8, by + 4);

var sc = 30 / Math.max(F, 1);
var fl = Math.max(F * sc, 8), cl = Math.max(Cf * sc, 8);
arrow(c1, by, fl, 0, "F", 2, -8);
arrow(c1, by, -cl, 0, "C", -14, -8);
arrow(c2, by, cl, 0, "C", 2, -8);
arrow(c1, by, 0, -24, "N1", -22, -2);
arrow(c1, by, 0, 24, "W1", -22, 10);
arrow(c2, by, 0, -24, "N2", -22, -2);
arrow(c2, by, 0, 24, "W2", -22, 10);
ctx.fillStyle = C.ink;
ctx.fillText("C pushes m1 backward", c1 - 60, by + 52);
ctx.fillText("and m2 forward: equal and opposite", c2 - 100, by + 52);

out.note = "a = F / (m1 + m2) = " + a.toFixed(2) + " m/s^2, contact force C = m2 a = " + Cf.toFixed(1) + " N";

var th = p.angle * Math.PI / 180;
var g = 9.8, m = p.mass, hold = p.hold;
var pad = 34;
var base = W - pad * 2;
var hgt = base * Math.tan(th);
var maxH = H - pad * 2.2;
if (hgt > maxH) { base = maxH / Math.max(Math.tan(th), 0.001); hgt = maxH; }
var x0 = pad, y0 = H - pad;
var x1 = x0 + base, y1 = y0 - hgt;
var ux = Math.cos(th), uy = -Math.sin(th);
var nx = -Math.sin(th), ny = -Math.cos(th);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

// the wedge
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.lineTo(x1, y0); ctx.closePath();
ctx.fill(); ctx.stroke();

// ground
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, y0); ctx.lineTo(W, y0); ctx.stroke();

// angle mark
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(x0, y0, 24, -th, 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", x0 + 28, y0 - 6);

// physics
var N, Fh, a;
if (hold > 0.5) { N = m * g / Math.cos(th); Fh = m * g * Math.tan(th); a = 0; }
else { N = m * g * Math.cos(th); Fh = 0; a = g * Math.sin(th); }

// where the block sits
var L = Math.sqrt(base * base + hgt * hgt);
var s;
if (hold > 0.5) { s = L * 0.55; }
else {
  var ppm = 14;
  var per = Math.sqrt(2 * (L * 0.85 / ppm) / Math.max(a, 0.05)) + 0.7;
  var tt = t % per;
  s = L * 0.9 - 0.5 * a * tt * tt * ppm;
  if (s < L * 0.06) s = L * 0.06;
}
var bx = x0 + ux * s, by = y0 + uy * s;
var bs = 26;
var cx = bx + nx * bs / 2, cy = by + ny * bs / 2;

// block
ctx.save();
ctx.translate(cx, cy);
ctx.rotate(-th);
ctx.fillStyle = C.paper; ctx.strokeStyle = C.ink;
ctx.fillRect(-bs / 2, -bs / 2, bs, bs);
ctx.strokeRect(-bs / 2, -bs / 2, bs, bs);
ctx.restore();

var sc = 58 / (m * g);
var arrow = function (dx, dy, label, lx, ly) {
  var ex = cx + dx, ey = cy + dy;
  ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ex, ey); ctx.stroke();
  var len = Math.sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  var hx = dx / len, hy = dy / len;
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - 7 * hx + 4 * hy, ey - 7 * hy - 4 * hx);
  ctx.lineTo(ex - 7 * hx - 4 * hy, ey - 7 * hy + 4 * hx);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText(label, ex + lx, ey + ly);
};

arrow(0, m * g * sc, "W = mg", -14, 14);
arrow(nx * N * sc, ny * N * sc, "N", -4, -6);
if (hold > 0.5) arrow(Fh * sc, 0, "F", 4, 4);

if (hold > 0.5) {
  out.note = "held: N = mg / cos(th) = " + N.toFixed(1) + " N, F = mg tan(th) = " + Fh.toFixed(1) +
             " N  (mg cos(th) would be " + (m * g * Math.cos(th)).toFixed(1) + " N)";
} else {
  out.note = "free: N = mg cos(th) = " + N.toFixed(1) + " N, a = g sin(th) = " + a.toFixed(2) + " m/s^2";
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
var g = 9.8, m = p.mass, a = p.accel;
var N = m * (g + a);
if (N < 0) N = 0;

var cw = Math.min(W * 0.42, 190);
var chh = H - 44;
var cx = W * 0.5 - cw / 2;
var cy = 26;

// shaft walls with moving ticks (motion cue)
var v = a * ((t % 3) - 1.5);
var off = ((v * 18) % 26 + 26) % 26;
ctx.strokeStyle = C.faint;
for (var i = -1; i < H / 26 + 1; i++) {
  var yy = cy + i * 26 + off;
  if (yy > cy && yy < cy + chh) {
    ctx.beginPath();
    ctx.moveTo(cx - 26, yy); ctx.lineTo(cx - 8, yy);
    ctx.moveTo(cx + cw + 8, yy); ctx.lineTo(cx + cw + 26, yy);
    ctx.stroke();
  }
}

// cable and car
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx + cw / 2, 0); ctx.lineTo(cx + cw / 2, cy); ctx.stroke();
ctx.fillStyle = C.paper;
ctx.fillRect(cx, cy, cw, chh); ctx.strokeRect(cx, cy, cw, chh);

// scale slab on the floor of the car
var fy = cy + chh;
ctx.fillStyle = C.faint; ctx.strokeStyle = C.rule;
ctx.fillRect(cx + cw / 2 - 34, fy - 12, 68, 12);
ctx.strokeRect(cx + cw / 2 - 34, fy - 12, 68, 12);

// person as a box
var px = cx + cw / 2 - 16, ph = 52;
ctx.fillStyle = C.paper; ctx.strokeStyle = C.ink;
ctx.fillRect(px, fy - 12 - ph, 32, ph);
ctx.strokeRect(px, fy - 12 - ph, 32, ph);

var mx = cx + cw / 2, my = fy - 12 - ph / 2;
var sc = 46 / (m * g);
var arrow = function (dx, dy, label, lx, ly) {
  var ex = mx + dx, ey = my + dy;
  ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(ex, ey); ctx.stroke();
  var len = Math.sqrt(dx * dx + dy * dy);
  if (len > 1) {
    var hx = dx / len, hy = dy / len;
    ctx.beginPath();
    ctx.moveTo(ex, ey);
    ctx.lineTo(ex - 7 * hx + 4 * hy, ey - 7 * hy - 4 * hx);
    ctx.lineTo(ex - 7 * hx - 4 * hy, ey - 7 * hy + 4 * hx);
    ctx.closePath(); ctx.fill();
  }
  ctx.fillStyle = C.ink;
  ctx.fillText(label, ex + lx, ey + ly);
};
arrow(0, m * g * sc, "W = mg", -18, 14);
arrow(0, -N * sc, "N (scale reading)", -34, -6);

// acceleration arrow outside the car
ctx.strokeStyle = C.figure; ctx.fillStyle = C.figure; ctx.lineWidth = 2;
var ax0 = cx + cw + 44, ay0 = cy + chh / 2;
var alen = a * 7;
ctx.beginPath(); ctx.moveTo(ax0, ay0); ctx.lineTo(ax0, ay0 - alen); ctx.stroke();
if (Math.abs(alen) > 2) {
  var sgn = alen > 0 ? 1 : -1;
  ctx.beginPath();
  ctx.moveTo(ax0, ay0 - alen);
  ctx.lineTo(ax0 - 4, ay0 - alen + 7 * sgn);
  ctx.lineTo(ax0 + 4, ay0 - alen + 7 * sgn);
  ctx.closePath(); ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("a = " + a.toFixed(1) + " m/s^2", ax0 - 18, ay0 + 30);

out.note = "scale reads N = m(g + a) = " + N.toFixed(1) + " N; at rest it would read " + (m * g).toFixed(1) + " N";
